    Data d = ds_tg();
    auto m = rcli::lm(Formula::parse("len ~ supp * factor(dose)", &d), d);
    check_names(m.formula.term_labels, {"supp", "factor(dose)", "supp:factor(dose)"}, "len ~ supp * factor(dose) labels");
    check_coef(m.coef, {"(Intercept)", "suppVC", "factor(dose)1", "factor(dose)2", "suppVC:factor(dose)1", "suppVC:factor(dose)2"}, {13.229999999999999, -5.2500000000000115, 9.4700000000000006, 12.83, -0.67999999999998928, 5.3300000000000143}, {1.1483530880416606, 1.6240165115015404, 1.6240165115015399, 1.6240165115015401, 2.2967061760833181, 2.296706176083319}, {11.520846800317946, -3.2327257529826117, 5.8312215010943387, 7.9001659830032045, -0.2960761838328077, 2.3207147938660198}, {3.602547609088197e-16, 0.0020924698287901498, 3.1756405463138078e-07, 1.4297120123799332e-10, 0.76830756536680489, 0.024108256604380523}, "len ~ supp * factor(dose)");
    check_assign(m.assign, {0, 1, 2, 2, 3, 3}, "len ~ supp * factor(dose) assign");
